use crate::{Method,Request,Response};use std::collections::{BTreeMap,BTreeSet};
#[derive(Debug,PartialEq,Eq)]pub enum RouteError{EmptyPattern,EmptyParameter,DuplicateParameter,DuplicateRoute}
type Handler=Box<dyn Fn(&Request)->Response+Send+Sync+'static>;struct Route{method:Method,pattern:String,segments:Vec<String>,handler:Handler}
#[derive(Default)]pub struct Router{routes:Vec<Route>}
impl Router{pub fn new()->Self{Self::default()}pub fn add<F>(&mut self,m:Method,p:impl Into<String>,h:F)->Result<(),RouteError>where F:Fn(&Request)->Response+Send+Sync+'static{let p=p.into();if p.is_empty(){return Err(RouteError::EmptyPattern)}if self.routes.iter().any(|r|r.method==m&&r.pattern==p){return Err(RouteError::DuplicateRoute)}let seg:Vec<String>=p.trim_matches('/').split('/').map(str::to_owned).collect();let mut names=BTreeSet::new();for s in &seg{if let Some(n)=s.strip_prefix(':'){if n.is_empty(){return Err(RouteError::EmptyParameter)}if !names.insert(n.to_owned()){return Err(RouteError::DuplicateParameter)}}}self.routes.push(Route{method:m,pattern:p,segments:seg,handler:Box::new(h)});Ok(())}
pub fn dispatch(&self,req:Request)->Response{let actual:Vec<&str>=req.path.trim_matches('/').split('/').collect();let mut found:Vec<(&Route,BTreeMap<String,String>,usize)>=Vec::new();for r in &self.routes{if r.segments.len()!=actual.len(){continue}let mut params=BTreeMap::new();let mut score=0;let mut ok=true;for(p,a)in r.segments.iter().zip(&actual){if let Some(n)=p.strip_prefix(':'){params.insert(n.to_owned(),(*a).to_owned());}else if p==a{score+=1}else{ok=false;break}}if ok{found.push((r,params,score));}}found.sort_by_key(|(_,_,s)|std::cmp::Reverse(*s));if let Some((r,p,_))=found.iter().find(|(r,_,_)|r.method==req.method){let mut q=req;q.path_params=p.clone();return(r.handler)(&q)}if found.is_empty(){Response::text(404,"not found")}else{Response::text(405,"method not allowed")}}}
#[cfg(test)]mod tests{use super::*;#[test]fn literal_route_precedes_parameter(){let mut r=Router::new();r.add(Method::Get,"/robots/:id",|_|Response::text(200,"parameter")).unwrap();r.add(Method::Get,"/robots/status",|_|Response::text(200,"literal")).unwrap();assert_eq!(r.dispatch(Request::new(Method::Get,"/robots/status",Vec::new())).body,b"literal");}#[test]fn duplicate_routes_rejected(){let mut r=Router::new();r.add(Method::Get,"/health",|_|Response::text(200,"ok")).unwrap();assert_eq!(r.add(Method::Get,"/health",|_|Response::text(200,"again")),Err(RouteError::DuplicateRoute));}}
